with RECs as (
    select 
        ph.PostId, ph.PostHistoryTypeId, ph.CreationDate,
        tier() over (partition by ph.PostId order by ph.CreationDate) rn
    from PostHistory ph 
    where ph.PostHistoryTypeId in (1,4,10)
),
RankedBadges as (
    select *,
        row_number() over (partition by UserId order by Date desc) badge_rank
    from Badges
    where Name like '%er%'
),
TopAnswerersCTE as (
    select owneruserid,
      count(*) as total_answers,
      sum(case when score > 10 then 1 else 0 end) high_score_answers
    from posts
    where PostTypeId = 2 and OwnerUserId is not null
    group by OwnerUserId
    having min(CreationDate) < '2020-01-01' and count(*) > 20
),
HighReputeQuestions as (
    select p.*,
        (select min(ph.CreationDate) from posthistory ph 
         where ph.PostId = p.Id and ph.PostHistoryTypeId = 10) close_date_zero,
        COALESCE(v_ups.all_upvotes, 0) total_upvotes
      from Posts p
       left join assets timelines
